import { useCallback, useEffect, useState } from 'react';

import { DomainError, isDomainError } from '../../core/errors';
import type { Topic } from '../../db/repositories/TopicRepository';
import { useServices } from '../../services/ServicesProvider';
import type { VoiceState } from '../../services/voice/VoiceSessionController';

export interface VoiceSessionView {
  state: VoiceState;
  // Last recognized utterance of the user.
  transcript: string | null;
  // The answer being generated by voice, for the chat bubble; null when none.
  streaming: string | null;
  micDenied: boolean;
  // Recent topics shown after "what topics do I have"; null when none were asked for.
  listedTopics: Topic[] | null;
  error: DomainError | null;
  toggle(): Promise<void>;
  // Same as saying "stop": ends the answer being prepared or read and listens again.
  interrupt(): void;
}

function toDomainError(error: unknown): DomainError {
  return isDomainError(error) ? error : new DomainError('provider_error', undefined, { cause: error });
}

export function useVoiceSession(
  topicId: number,
  onExchange: () => Promise<void>,
  onTopicChange: (topic: Topic) => void,
): VoiceSessionView {
  const { voice } = useServices();
  const [state, setState] = useState<VoiceState>('idle');
  const [transcript, setTranscript] = useState<string | null>(null);
  const [streaming, setStreaming] = useState<string | null>(null);
  const [micDenied, setMicDenied] = useState(false);
  const [listedTopics, setListedTopics] = useState<Topic[] | null>(null);
  const [error, setError] = useState<DomainError | null>(null);

  // Leaving the conversation ends the voice session.
  useEffect(() => () => void voice.stop(), [voice]);

  const toggle = useCallback(async () => {
    if (voice.current !== 'idle') {
      await voice.stop();
      setStreaming(null);
      return;
    }
    setError(null);
    const result = await voice.start(topicId, {
      onState: setState,
      onHeard: setTranscript,
      onTopicChange: (topic) => {
        setListedTopics(null);
        onTopicChange(topic);
      },
      onTopicList: setListedTopics,
      onTranscript: (text) => {
        setTranscript(text);
        setStreaming('');
      },
      onToken: (token) => setStreaming((current) => (current ?? '') + token),
      onExchange: () => {
        setStreaming(null);
        void onExchange();
      },
      onError: (failure) => {
        setStreaming(null);
        setError(toDomainError(failure));
      },
    });
    setMicDenied(result === 'permission_denied');
  }, [onExchange, onTopicChange, topicId, voice]);

  const interrupt = useCallback(() => void voice.interrupt(), [voice]);

  return { state, transcript, streaming, micDenied, listedTopics, error, toggle, interrupt };
}
